learn=[('Opt in and inspect availability', 'Task tools depend on the bundled runtime and model. This app explicitly enables CLAUDE_CODE_ENABLE_TODO_TOOLS, selects native Task tools and shows the actual SDK initialization tool list.'), ('Correlate real task IDs', 'TaskCreate input describes a task. Its ID comes from the correlated user tool result, in tool_use_result.task.id. Pair that result with the request through tool_use_id.'), ('Track confirmed lifecycle changes', 'Use pending, in_progress and completed. TaskUpdate deleted removes a task. This tracker waits for successful tool results before changing confirmed state, so a denied update cannot falsely complete a task.'), ('Render active work clearly', 'Show activeForm while a task is in_progress and subject otherwise. Count completed and in-progress tasks. Pending tasks use an open circle, not a failure symbol.'), ('Compare progress with actual work', 'The website experiment creates home, about and stylesheet tasks, writes the three bounded files and updates progress. Inspect independently read file content; a completed checklist is an agent report, not an independent test.'), ('Handle variations and failure', 'Read raw taskId, id or task_id and activeForm or active_form defensively. Compare TaskList, TaskGet, deletion, failed updates, the legacy TodoWrite replacement list and a real turn-limit result plus exception.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3137\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Use Node.js 24+, model API access and credit. Windows may require Git Bash. Python is only needed to regenerate student pages.', 'node --version\nnpm --version'), ('Install and configure .env', 'Enter the app folder, install locked dependencies, preserve an existing .env and enter your own model key privately.', 'cd .\\agent-sdk\\lesson37-todo-progress\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and navigate', 'Keep the terminal open and visit the printed URL. Five navigation buttons link the lab, learning goals, setup, UML diagram and source walkthrough.', 'npm start\n# http://127.0.0.1:3137'), ('Watch a real plan and website build', 'Compare Plan only with Lifecycle. Run Website and watch three tasks progress as actual HTML and CSS files are written. The explicit work hook delay is 1.8 seconds per classroom Read or Write.', 'npm run sample:env -- plan\nnpm run sample:env -- lifecycle\nnpm run sample:env -- website'), ('Inspect IDs, labels and deletion', 'Compare the actual create tool request with its paired result. Run Delete, Rename and Read back; inspect TaskList and TaskGet output. Raw key aliases are supported by the tracker.', 'npm run sample:env -- delete\nnpm run sample:env -- rename\nnpm run sample:env -- readback'), ('Compare failure, legacy tools and limits', 'Denied update must leave confirmed progress pending. Legacy enables TodoWrite with CLAUDE_CODE_ENABLE_TASKS=0 and replaces the entire list. Capped records an actual error_max_turns result and the following exception. Download observations and run offline tests.', 'npm run sample:env -- denied\nnpm run sample:env -- legacy\nnpm run sample:env -- capped\nnpm test')]
specs=[('Validate the selected experiment', 'src/modes.ts', 'export function validateConfig', 'Accept a named classroom experiment. Browser input cannot replace the tools, prompts or filesystem scope.', 0, 1, 7), ('Opt in to native task tools', 'src/agent.ts', 'CLAUDE_CODE_ENABLE_TODO_TOOLS:', 'Enable todo tools for the SDK subprocess while preserving inherited environment values. The legacy experiment selects TodoWrite instead.', 1, 2, 4), ('Start the actual SDK query', 'src/agent.ts', 'const q = query', 'A real query owns planning and execution. Drain the loop so the final result and any following exception are observed.', 1, 2, 3), ('Inspect actual tool availability', 'src/agent.ts', 'discoveredTools = message.tools;', 'SDK initialization reports the actual runtime tool list. Do not infer availability solely from the configured model name.', 2, 1, 3), ('Receive structured task requests', 'src/agent.ts', 'if (block.type === "tool_use")', 'Assistant tool_use blocks contain task requests. Record them before tracking their eventual correlated result.', 2, 1, 5), ('Keep requests provisional', 'src/tracker.ts', 'request(call: Call)', 'Store each task request once by tool-use ID. A request alone does not add a confirmed task or change its status.', 1, 3, 7), ('Correlate actual tool results', 'src/agent.ts', 'tracker.result(block, message.tool_use_result);', 'Pair user tool_result.tool_use_id with the earlier tool call. Read the structured tool_use_result object carried on that same user message.', 2, 3, 3), ('Read assigned task IDs', 'src/tracker.ts', 'const id = text(object(out.task).id);', 'TaskCreate results supply task.id. A missing ID does not create a synthetic Task-system identifier.', 3, 3, 9), ('Confirm lifecycle updates', 'src/tracker.ts', 'const id = text(input.taskId', 'Accept raw identifier aliases, locate a known task and reject explicit failed execution. Apply updates only after a successful result.', 3, 3, 5), ('Remove an obsolete task', 'src/tracker.ts', 'if (input.status === "deleted")', 'Successful deletion removes the task from the map and progress denominator. Keep the confirmed deletion in history.', 3, 1, 9), ('Count confirmed progress', 'src/tracker.ts', 'completed: tasks.filter', 'Count completed and active tasks from the confirmed snapshot. Pending tool requests are reported separately.', 3, 1, 5), ('Render active work labels', 'src/client.ts', 'const label =', 'Show activeForm only while in_progress; use the subject otherwise. Build browser text nodes so task labels cannot inject HTML.', 1, 0, 7), ('Inspect actual work and cleanup', 'src/agent.ts', 'const inspected = await workspace.inspect();', 'Read the actual bounded website files and fixture before emitting evidence. The finally block cleans only the verified temporary run directory.', 4, 1, 9)]
document('/','Todo tracking. <em>See the progress.</em>','Correlate actual task calls with results and render confirmed progress.','<div class="flow"><div><b>01 · Plan</b><p>Create tasks and receive IDs</p></div><span>→</span><div><b>02 · Work</b><p>Confirm actual tool results</p></div><span>→</span><div><b>03 · Verify</b><p>Render progress and inspect files</p></div></div><section class="panel" id="controls"><h2>Explore todo tracking</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Todo experiment</label><select id="mode"><option value="plan">Plan only · confirmed pending task</option><option value="lifecycle">Lifecycle · pending to completed</option><option value="website">Website lab · three real files</option><option value="delete">Delete · remove obsolete work</option><option value="rename">Labels · subject and activeForm</option><option value="readback">Read back · TaskList and TaskGet</option><option value="denied">Denied update · preserve confirmed state</option><option value="legacy">Legacy · TodoWrite replacement list</option><option value="capped">Turn limit · result and exception</option></select><button id="run" class="primary" disabled>Run todo experiment →</button><p class="meta">Every experiment uses the real SDK. The classroom work hook adds a deliberate 1.8-second delay so in-progress work is visible. Writes are limited to three disposable website files. The SDK budget threshold is $0.60 per query.</p></section><div class="workspace"><section class="panel" id="progress-panel"><h2 id="status" aria-live="polite">Ready</h2><h3 id="summary" aria-live="polite">No confirmed tasks yet</h3><p id="pending" class="meta">Waiting for actual SDK task results.</p><ul id="tasks" aria-label="Confirmed task progress"></ul><p class="meta">Task IDs come from actual results. Status updates are confirmed after successful execution.</p></section><section class="panel" id="chat-panel"><h2>Actual agent response</h2><div id="conversation"></div></section></div><section class="step" id="option-panel"><h2>Options actually passed</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre></section><section class="step" id="discovery-panel"><h2>Tools discovered by the actual runtime</h2><pre class="json-view"><code id="discovery" class="language-json">[]</code></pre><p>Inspect actual availability rather than assuming a tool exists for every model.</p></section><section class="step" id="changes-panel"><h2>Correlated lifecycle history</h2><pre class="json-view"><code id="changes" class="language-json">[]</code></pre><p>A failed update remains visible here while the confirmed checklist keeps its previous status.</p></section><section class="step" id="tracker-panel"><h2>Confirmed task tracker</h2><pre class="json-view"><code id="tracker" class="language-json">{}</code></pre></section><section class="step" id="files-panel"><h2>Actual generated website files</h2><pre class="json-view"><code id="files" class="language-json">[]</code></pre><p>The host independently reads these files before cleaning up the temporary project. A completed task list alone does not verify their content.</p></section><section class="step" id="observation-panel"><h2>Inspect actual SDK calls and results</h2><label for="observation-select">Observed arrival sequence</label><select id="observation-select"><option>No observations yet</option></select><pre class="json-view"><code id="selected-observation" class="language-json">{}</code></pre></section><section class="step" id="results-panel"><h2>Final SDK result</h2><pre class="json-view"><code id="result" class="language-json">{}</code></pre><p id="exception" class="note"></p><p>A one-shot query can yield error_max_turns and then throw. Both observations are preserved.</p></section><section class="step" id="evidence-panel"><h2>Independent run evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><button id="download">Download actual observations</button></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Learn task lifecycles, real IDs and live browser progress.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your .env configuration</h2>'+snippet(env,'dotenv')+'<p>Only your model key is required. Keep it local and restart after edits. Existing shell variables take precedence.</p></section><section class="note"><h3>Troubleshooting</h3><p>Use Node 24+, API credit and a supported model. Configure Git Bash on Windows if requested. If the port is occupied, use the printed existing-app URL or change PORT. Choose a todo experiment, watch confirmed lifecycle changes and inspect actual calls, results and files. Change PORT if 3137 is occupied. The classroom Read and Write hooks deliberately pause for 1.8 seconds.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install the SDK, configure your key and run the classroom comparisons.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','Agent SDK Query','TaskTracker','Website files']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 37 · Plan → correlate → work → verify</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{min(x1,x2)+10}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">The diagram groups native Task tools, the confirmed-state tracker and bounded website work. SDK tool results assign task IDs. The host sends actual snapshots to the browser through SSE.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen source-linked todo workflow steps"></div>'+walk)

reference=[('Tool availability', 'The bundled Claude Code runtime selects task-tool defaults by model. This app explicitly opts in and displays actual initialized tools. Native Task tools and legacy TodoWrite are separate verified experiments.'), ('Progress is reported work', 'A completed task means the agent successfully updated its list. It is not proof that the underlying work is correct. Inspect independently read files, native feedback and application-specific checks.'), ('Requests versus confirmed state', 'The browser receives both requests and results. This tracker commits status changes after successful correlated results, improving on request-only progress displays when tools can fail or be denied.'), ('Task IDs and aliases', 'TaskCreate assigns IDs in tool_use_result.task.id. Raw model input can use taskId, id or task_id and activeForm or active_form. Unknown IDs are not silently synthesized.'), ('Legacy list semantics', 'TodoWrite replaces an entire list. It does not supply TaskCreate IDs. This interface labels its own display keys legacy-row-N; they are explicitly local presentation keys.'), ('Lifecycle and costs', 'TaskCreate, TaskUpdate, TaskList and TaskGet are planning tools, distinct from background-task system notifications. This app launches no subagents or background work. Queries are bounded by turns, a six-minute host timeout and a $0.60 SDK budget threshold, which is not a prepaid cap.')]
document('/walkthrough.html','How the app <em>was built.</em>','Every architecture step has source-linked coloured code.',cards(reference)+walk)
readme='# Claude Agent SDK · Lesson 37 · Todo tracking and live progress\n\nFive linked student pages, large text, actual SDK experiments and coloured code in all thirteen UML steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson37-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson37-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations use `cd .\\agent-sdk\\lesson37-todo-progress`. Open http://127.0.0.1:3137 and keep the terminal running. Node.js 24+, API credit and model access are required. Windows may require Git Bash.\n\n## Create your .env file\n\nPreserve an existing file. Enter your own model key, then restart. Existing shell values take precedence.\n\n```dotenv\n'+env+'\n```\n\nNo GitHub token or Managed Agents IDs are required. Secrets, dependencies and teaching media stay outside Git.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for step in steps:readme+=f'### {step["number"]}. {step["title"]}\n\n{step["explanation"]}\n\nSource: `{step["source"]}`, selected lines {step["firstLine"]}–{step["lastLine"]}. Surrounding code omitted.\n\n```typescript\n{step["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## References\n\n- [Official SDK todo-tracking documentation](https://code.claude.com/docs/en/agent-sdk/todo-tracking)\n- [TypeScript SDK reference](https://code.claude.com/docs/en/agent-sdk/typescript)\n\nRegenerate student pages with `python scripts/build-pages.py`. Run `npm test` for offline boundaries, review lifecycle, workspace and startup checks.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
print('Built five Lesson 37 pages and thirteen source-linked UML steps.')

(PUBLIC/"style.css").write_text((PUBLIC/"style.css").read_text(encoding="utf-8")+'\n#tasks{list-style:none;padding:0;margin:20px 0;max-height:480px;overflow:auto}.task{padding:16px 20px;border:1px solid var(--line);border-radius:14px;background:var(--soft);margin:12px 0;font-size:23px}.task .meta{margin:6px 0 0}.task.in_progress{border-left:6px solid #9344ff;background:var(--soft)}.task.completed{border-left:6px solid #009e80}.markdown-body{font-size:22px;line-height:1.6}#conversation{max-height:550px;overflow:auto}.json-view{max-height:380px}#progress-panel{align-self:start}#conversation article{border-bottom:1px solid var(--line);margin:12px 0}#summary{font-size:28px}\n',encoding="utf-8")
